 'transaction_isolation',current_setting('transaction_isolation'),'transaction_read_only',current_setting('transaction_read_only'),
 'window',jsonb_build_object('start_utc',TIMESTAMPTZ '2026-11-11T20:00:00.000Z','end_utc',TIMESTAMPTZ '2026-11-12T04:00:00.000Z','cutoff_utc',TIMESTAMPTZ '2026-11-12T02:56:23.000Z',
