   'boundary','[start,cutoff)','requested_elapsed_seconds',extract(epoch FROM (TIMESTAMPTZ '2026-11-12T02:56:23.000Z'-TIMESTAMPTZ '2026-11-11T20:00:00.000Z'))),
 'coverage',jsonb_build_object('inventory','all public DSF mappings; no numeric-department filter',
   'detailed_source_count',6,'detailed_sources','[{"name":"CutGrind 6 1-24-77","sourceId":"666e2c9a-545e-4ce0-b9f2-eb5c8c579c5c","opId":"5212149b-76d3-48be-97eb-138376036024","lineId":"0aab0c6e-4456-46b9-9a0b-4de7d0a57e07","whiteboardId":null},{"name":"CutGrind 4 1-24-78","sourceId":"dd21c21b-a57e-4d61-afcb-c2749480e3f9","opId":"cafd4e72-bc71-426d-a726-6c6f40f1788b","lineId":"dca4597f-4de0-4324-97ac-42b215843791","whiteboardId":null},{"name":"CutGrind 3 1-24-79","sourceId":"1d6e8617-c497-45ca-8cc7-af92f4556b43","opId":"ca94b716-ff99-426a-b63c-c79e49c5692e","lineId":"5e7b362f-2cb5-4491-904e-2e1f107cc97e","whiteboardId":"9b176c57-b77a-4dd7-b1be-28bb75b7c9e6"},{"name":"CutGrind 7 1-24-80","sourceId":"b6c0d002-871b-4561-8346-1e7a25865193","opId":"b86d1e5c-da15-41fd-9dfc-2e1ee92867fb","lineId":"a7e3f04c-f35a-4811-b749-2343561708aa","whiteboardId":null},{"name":"CutGrind 5 1-24-81","sourceId":"4ef46158-f861-4ea3-828e-5a07710a80c0","opId":"07635887-57de-47ae-9c69-6a3856bda303","lineId":"7aa4c439-39cc-4a25-85db-553ba667bbca","whiteboardId":null},{"name":"181 - 1","sourceId":"c40b52fb-6f80-450c-897d-d61ce5539aac","opId":"c13a1365-8420-419e-857c-445f5df82fb3","lineId":"c6429cd9-64b3-4ea3-9f9d-fd291612488e","whiteboardId":"e7fb8890-3071-4aa9-9746-cb038a4d3fc0"}]'::jsonb,
   'full_plant_history',false,'historical_mutability','current snapshot may include corrections made after the report cutoff'),
