 WHERE n.nspname='public' AND (c.relname IN ('tbl_whiteboard_machines','tbl_whiteboard','tbl_op','tbl_line','tbl_department','operation_detail','tbl_location','tbl_area','tbl_cell','tbl_plant','tbl_location_config','tbl_threshold_color','tbl_whiteboard_comment_shift','tbl_whiteboard_comment','tbl_whiteboard_cycles_master','tbl_whiteboard_cycles','tbl_whiteboard_cycles_current','tbl_whiteboard_cycles_old','tbl_whiteboard_daily_aggregate','tbl_op_state','tbl_line_state','tbl_op_state_reason','tbl_line_state_reason','tbl_op_state_category','tbl_op_rated_speed','tbl_line_rated_speed','tbl_op_cycle_time','tbl_line_cycle_time','tbl_op_cycle_bounds','tbl_op_count_target','tbl_line_count_target','tbl_line_daily_target','tbl_op_count_rework','tbl_line_count_rework','tbl_op_oee','tbl_line_oee','tbl_shift','tbl_shift_schedule','vw_oa_state_data') OR c.relname ~* '(part|config|comment|threshold|shift)') ORDER BY c.relname,i.relname
 LIMIT 10001),
numbered AS (SELECT to_jsonb(b) record,row_number() OVER () ordinal FROM bounded b)
SELECT jsonb_build_object('kind','DATASET','dataset','INDEX_CATALOG',
 'manifest',jsonb_build_object('status',CASE WHEN count(*)>10000 THEN 'truncated' ELSE 'complete' END,
 'returned_rows',LEAST(count(*),10000),'observed_rows',count(*),'row_limit',10000,'truncated',count(*)>10000,'note','No EXPLAIN ANALYZE or full-table counts are executed.'),
