-- PARTITION_CATALOG
WITH bounded AS MATERIALIZED (SELECT pn.nspname AS parent_schema,p.relname AS parent,
 cn.nspname AS child_schema,c.relname AS child,pg_catalog.pg_get_expr(c.relpartbound,c.oid,true) AS partition_bound
 FROM pg_catalog.pg_inherits i JOIN pg_catalog.pg_class p ON p.oid=i.inhparent
 JOIN pg_catalog.pg_namespace pn ON pn.oid=p.relnamespace JOIN pg_catalog.pg_class c ON c.oid=i.inhrelid
 JOIN pg_catalog.pg_namespace cn ON cn.oid=c.relnamespace
 WHERE pn.nspname='public' AND (p.relname ~ '^tbl_(whiteboard_cycles|op_|line_)' OR c.relname ~ '^tbl_(whiteboard_cycles|op_|line_)')
 ORDER BY p.relname,c.relname
 LIMIT 10001),
numbered AS (SELECT to_jsonb(b) record,row_number() OVER () ordinal FROM bounded b)
SELECT jsonb_build_object('kind','DATASET','dataset','PARTITION_CATALOG',
 'manifest',jsonb_build_object('status',CASE WHEN count(*)>10000 THEN 'truncated' ELSE 'complete' END,
 'returned_rows',LEAST(count(*),10000),'observed_rows',count(*),'row_limit',10000,'truncated',count(*)>10000,'note','Partition/inheritance structure; partition bounds can expose coverage without scanning history.'),
 'records',COALESCE(jsonb_agg(record ORDER BY ordinal) FILTER (WHERE ordinal<=10000),'[]'::jsonb)) FROM numbered;
SELECT NOT EXISTS (
 SELECT 1 FROM (VALUES ('tbl_whiteboard_machines','id'),('tbl_whiteboard_machines','whiteboard_id'),('tbl_whiteboard_machines','op_id'),('tbl_whiteboard_machines','line_id'),('tbl_whiteboard_machines','active'),('tbl_whiteboard','id'),('tbl_whiteboard','name'),('tbl_whiteboard','active'),('tbl_op','id'),('tbl_op','name'),('tbl_op','line_id'),('tbl_op','asset_number'),('tbl_line','id'),('tbl_line','name'),('tbl_line','department_id'),('tbl_line','loc_id'),('tbl_line','area_id'),('tbl_line','cell_id'),('tbl_line','asset_number'),('tbl_department','id'),('tbl_department','name')) expected(relation,column_name)
 WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c
   JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
   JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid
   WHERE n.nspname='public' AND c.relname=expected.relation AND c.relkind IN ('r','p','v','m','f')
