WITH chosen AS (
 SELECT * FROM jsonb_to_recordset('[{"name":"CutGrind 6 1-24-77","sourceId":"666e2c9a-545e-4ce0-b9f2-eb5c8c579c5c","opId":"5212149b-76d3-48be-97eb-138376036024","lineId":"0aab0c6e-4456-46b9-9a0b-4de7d0a57e07","whiteboardId":null},{"name":"CutGrind 4 1-24-78","sourceId":"dd21c21b-a57e-4d61-afcb-c2749480e3f9","opId":"cafd4e72-bc71-426d-a726-6c6f40f1788b","lineId":"dca4597f-4de0-4324-97ac-42b215843791","whiteboardId":null},{"name":"CutGrind 3 1-24-79","sourceId":"1d6e8617-c497-45ca-8cc7-af92f4556b43","opId":"ca94b716-ff99-426a-b63c-c79e49c5692e","lineId":"5e7b362f-2cb5-4491-904e-2e1f107cc97e","whiteboardId":"9b176c57-b77a-4dd7-b1be-28bb75b7c9e6"},{"name":"CutGrind 7 1-24-80","sourceId":"b6c0d002-871b-4561-8346-1e7a25865193","opId":"b86d1e5c-da15-41fd-9dfc-2e1ee92867fb","lineId":"a7e3f04c-f35a-4811-b749-2343561708aa","whiteboardId":null},{"name":"CutGrind 5 1-24-81","sourceId":"4ef46158-f861-4ea3-828e-5a07710a80c0","opId":"07635887-57de-47ae-9c69-6a3856bda303","lineId":"7aa4c439-39cc-4a25-85db-553ba667bbca","whiteboardId":null},{"name":"181 - 1","sourceId":"c40b52fb-6f80-450c-897d-d61ce5539aac","opId":"c13a1365-8420-419e-857c-445f5df82fb3","lineId":"c6429cd9-64b3-4ea3-9f9d-fd291612488e","whiteboardId":"e7fb8890-3071-4aa9-9746-cb038a4d3fc0"}]'::jsonb) AS x(name text, "sourceId" uuid, "opId" uuid, "lineId" uuid, "whiteboardId" uuid)
), resolved AS (
 SELECT s.name,s."sourceId" AS source_id,s."opId" AS op_id,s."lineId" AS line_id,s."whiteboardId" AS expected_whiteboard_id,
   wm.whiteboard_id,w.name AS current_name,wm.op_id AS current_op_id,wm.line_id AS current_line_id,
   o.line_id AS operation_line_id,l.name AS line_name,wm.active AS mapping_active,w.active AS whiteboard_active,
   CASE WHEN wm.id IS NULL THEN 'missing_source'
        WHEN w.id IS NULL OR o.id IS NULL OR l.id IS NULL OR d.id IS NULL THEN 'missing_related_identity'
        WHEN wm.op_id IS DISTINCT FROM s."opId" OR wm.line_id IS DISTINCT FROM s."lineId"
          OR (s."whiteboardId" IS NOT NULL AND wm.whiteboard_id IS DISTINCT FROM s."whiteboardId")
          OR o.line_id IS DISTINCT FROM s."lineId" OR w.name IS DISTINCT FROM s.name THEN 'identity_mismatch'
        WHEN wm.active IS DISTINCT FROM true OR w.active IS DISTINCT FROM true THEN 'inactive_source'
        ELSE 'validated' END AS identity_status
 FROM chosen s LEFT JOIN public.tbl_whiteboard_machines wm ON wm.id=s."sourceId"
 LEFT JOIN public.tbl_whiteboard w ON w.id=wm.whiteboard_id
 LEFT JOIN public.tbl_op o ON o.id=wm.op_id LEFT JOIN public.tbl_line l ON l.id=wm.line_id
 LEFT JOIN public.tbl_department d ON d.id=l.department_id
)
