   'status',CASE WHEN v.identity_status<>'validated' THEN v.identity_status WHEN d.observed_rows>10000 THEN 'truncated' ELSE 'complete' END,
   'returned_rows',LEAST(d.observed_rows,10000),'observed_rows',d.observed_rows,'row_limit',10000,
   'truncated',d.observed_rows>10000,'scope','selected_sources','note','Raw stream; no production/downtime formula inferred.'),
 'records',d.records)
FROM resolved v CROSS JOIN LATERAL (
 SELECT count(*) AS observed_rows,COALESCE(jsonb_agg(b.record ORDER BY b.ordinal) FILTER (WHERE b.ordinal<=10000),'[]'::jsonb) AS records
 FROM (SELECT to_jsonb(q) AS record,row_number() OVER () AS ordinal FROM (
 SELECT r.id,r.line_id,r."timestamp",r.count,r.reason,r.length FROM public.tbl_line_count_rework r
 WHERE v.identity_status='validated' AND r.line_id=v.line_id AND r."timestamp">=TIMESTAMPTZ '2026-11-11T20:00:00.000Z' AND r."timestamp"<TIMESTAMPTZ '2026-11-12T02:56:23.000Z'
